// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(bool dummy) internal {
        dummy = false;
        address beforeOwner;
        try c.smartfix_owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address afterOwner;
        try c.smartfix_owner() returns (address __r) { afterOwner = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(!reverted && beforeOwner == afterOwner);
    }

    function testFuzz_run(bool dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
